 1	import React from 'react';
 2	import {RecordStatus} from './editor';
 3	
 4	export function RecordTitle({level=3, ...props}:
 5	  React.HTMLAttributes<HTMLHeadingElement> & {level?: 2 | 3 | 4 | 5 | 6}) {
 6	  const Heading = `h${level}` as 'h2' | 'h3' | 'h4' | 'h5' | 'h6';
 7	  return <Heading {...props}/>;
 8	}
 9	
10	// Keep article semantics and separate native controls: wrapping the entire card
11	// in a button would nest secondary buttons/inputs and break keyboard behavior.
12	const interactive = 'button,a,input,select,textarea,label,summary,dialog,' +
13	  '[role="button"],[role="link"],[role="checkbox"],[role="switch"],[role="menuitem"],' +
14	  '[role="tab"],[role="radio"],[role="combobox"],[role="textbox"],[role="searchbox"],' +
15	  '[role="slider"],[role="spinbutton"],[role="option"],[role="menuitemcheckbox"],[role="menuitemradio"],' +
16	  '[contenteditable]:not([contenteditable="false"]),[data-card-action]';
17	
18	export function RecordCard({name, onOpen, headingLevel=3, children, actions, statuses, onClick, ...props}:
19	  React.HTMLAttributes<HTMLElement> & {name: string; onOpen?: () => void;
20	    headingLevel?: 2 | 3 | 4 | 5 | 6; actions?: React.ReactNode;
21	    statuses?: React.ComponentProps<typeof RecordStatus>[]}) {
22	  const title = <RecordTitle level={headingLevel}>
23	    {onOpen ? <button type="button" onClick={onOpen}>{name}</button> : name}
24	  </RecordTitle>;
25	  const content=<>{title}{statuses?.map((status,index)=><RecordStatus key={index} {...status}/>)}{children}</>;
26	  return <article {...props} aria-label={name} onClick={event => {
27	    onClick?.(event);
28	    if (!onOpen || event.defaultPrevented) return;
29	    const target = event.target instanceof Element ? event.target : null;
30	    if (target?.closest(interactive)) return;
31	    onOpen();
32	  }}>
33	    {actions != null ? <>
34	      <div style={{minBlockSize: onOpen ? '8rem' : undefined}}>{content}</div>
35	      <div data-card-action style={{display:'flex', flexWrap:'wrap', alignItems:'center', gap:8}}>
36	        {actions}
37	      </div>
38	    </> : content}
39	  </article>;
40	}
 1	import React, {useId, useState} from 'react';
 2	
 3	// Keep subordinate controls in their owner's DOM and retain local draft state.
 4	export function EditorSection({label, children, defaultOpen=false, open, onOpenChange}: {
 5	  label: string; children: React.ReactNode; defaultOpen?: boolean;
 6	  open?: boolean; onOpenChange?: (open: boolean) => void;
 7	}) {
 8	  const id=useId(), [expanded,setExpanded]=useState(defaultOpen), visible=open ?? expanded;
 9	  return <section>
10	    <button type="button" aria-expanded={visible} aria-controls={id} onClick={()=>{
11	      if (open === undefined) setExpanded(!visible);
12	      onOpenChange?.(!visible);
13	    }}>{label}</button>
14	    <div id={id} hidden={!visible}>{children}</div>
15	  </section>;
16	}
17	
18	export function RecordStatus({label, icon, active=true}: {
19	  label: string; icon?: React.ReactNode; active?: boolean;
20	}) {
21	  return active ? <span role="img" aria-label={label} title={label}>
22	    <span aria-hidden="true">{icon ?? label}</span>
23	  </span> : null;
24	}
